svg.script:

(function () {
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduceMotion) return;

  var svg = document.getElementById('svg1');
  var pushEls = Array.prototype.slice.call(document.querySelectorAll('.hy-push'));

  // Order matches document order of the .hy-push wrappers above:
  // na, cl, k, citrate-1, ca, lactate, mg, glycine, dextrose, citric-acid, mogrosides.
  // The two citrate-family structures are NOT the same species: citrate-1 (near Mg) is drawn
  // fully deprotonated (-COO/-O terminal groups, no OH) — the citrate anion — while the one
  // near Ca is drawn with explicit -OH on all three carboxyls — neutral citric acid. Confirmed
  // by rendering and visually comparing the two structures, not assumed from position/symmetry.
  var ION_NAMES = ['Sodium', 'Chloride', 'Potassium', 'Citrate', 'Calcium', 'Lactate', 'Magnesium', 'Glycine', 'Dextrose', 'Citric Acid', 'Mogrosides'];

  var wordmark = document.getElementById('text11');
  var label = document.getElementById('hy-selection-label');
  var wbox = wordmark.getBBox();
  label.setAttribute('x', (wbox.x + wbox.width / 2).toFixed(3));
  label.setAttribute('y', (wbox.y + wbox.height / 2).toFixed(3));

  // Sequential blink rather than a crossfade: fade the visible one out
  // fully, then fade the other in — never both mid-fade at once. Each
  // phase's duration must match the CSS transition on #text11/#hy-selection-label.
  var BLINK_PHASE_MS = 150;
  var blinkTimer = null;
  function blinkTo(showLabel, name) {
    if (blinkTimer !== null) { clearTimeout(blinkTimer); blinkTimer = null; }
    var hiding = showLabel ? wordmark : label;
    var revealing = showLabel ? label : wordmark;
    hiding.style.opacity = '0';
    blinkTimer = setTimeout(function () {
      blinkTimer = null;
      if (name !== undefined) label.textContent = name;
      revealing.style.opacity = '1';
    }, BLINK_PHASE_MS);
  }

  // Mass-spring-damper per element, all in screen-px units: the cursor's
  // frame-to-frame movement (its velocity, not its position) kicks an
  // element's own velocity; that velocity decays gradually (viscosity)
  // and a weak spring pulls it back toward rest — so motion persists and
  // fades after the cursor stops, instead of snapping to a cursor-relative spot.
  var PUSH_RADIUS = 55; // screen px, radius of cursor influence
  var IMPULSE_STRENGTH = 0.02; // fraction of cursor's per-frame movement transferred to velocity at zero distance
  var MAX_MOUSE_STEP_PX = 15; // screen px, cap on a single frame's cursor movement before it's treated as an impulse (avoids a jarring spike on fast flicks)
  var DRAG = 0.92; // velocity retained per 16.67ms (lower = thicker fluid, stops sooner)
  var SPRING_K = 0.012; // per-16.67ms pull-back-to-rest strength (lower = slower, more gradual return home)
  var MAX_DISPLACEMENT_PX = 8; // screen px, clamp so a fast swipe can't fling an element off
  var HOVER_SCALE = 1.08; // scale applied to the hovered element, as if selected
  var SCALE_EASE = 0.15; // smoothing factor per frame for the hover scale transition
  // Selection is proximity + dwell based rather than exact hit-testing: the
  // nearest ion within HOVER_RADIUS is a "candidate", but only becomes
  // hovered once the cursor has sat near it, slowly, for HOVER_DELAY_MS —
  // so passing over an ion while chasing the fluid motion doesn't select it.
  var HOVER_RADIUS = 45; // screen px, buffer zone around each ion that counts as "near it"
  var HOVER_DELAY_MS = 300; // must be the nearest candidate continuously for this long
  var MAX_HOVER_SPEED_PX = 4; // screen px moved per frame; faster than this resets the dwell timer

  var state = pushEls.map(function (el) {
    return { el: el, posX: 0, posY: 0, velX: 0, velY: 0, scale: 1 };
  });

  var hoveredIndex = null; // committed selection, drives dim/scale
  var candidateIndex = null; // nearest ion within HOVER_RADIUS this frame
  var hoverTimerMs = 0; // how long candidateIndex has been held, slowly

  var mouseX = null, mouseY = null, prevMouseX = null, prevMouseY = null, hasMouse = false;
  window.addEventListener('mousemove', function (e) {
    mouseX = e.clientX; mouseY = e.clientY; hasMouse = true;
  }, { passive: true });
  window.addEventListener('mouseleave', function () { hasMouse = false; }, { passive: true });

  function svgScale() {
    var r = svg.getBoundingClientRect();
    var vb = svg.viewBox.baseVal;
    return r.width / vb.width; // screen px per user unit
  }

  var lastTime = null;
  function tick(now) {
    if (lastTime === null) lastTime = now;
    var rawDtMs = now - lastTime; // real elapsed ms, uncapped — used for the hover dwell timer
    var steps = Math.min(rawDtMs / 16.67, 4); // frame-rate-independent; cap catch-up after a throttled/backgrounded gap
    lastTime = now;

    var scale = svgScale();
    var mvx = 0, mvy = 0, rawSpeed = 0;
    if (hasMouse && prevMouseX !== null) {
      mvx = mouseX - prevMouseX;
      mvy = mouseY - prevMouseY;
      rawSpeed = Math.sqrt(mvx * mvx + mvy * mvy); // unclamped cursor speed this frame, for the hover speed gate
      if (rawSpeed > MAX_MOUSE_STEP_PX) {
        var mvK = MAX_MOUSE_STEP_PX / rawSpeed;
        mvx *= mvK; mvy *= mvK;
      }
    }
    prevMouseX = mouseX; prevMouseY = mouseY; // consumed: a stationary cursor contributes no further impulse

    // Find the nearest ion to the cursor, if any is within the buffer radius.
    var candidate = null, candidateDist = Infinity;
    if (hasMouse) {
      for (var ci = 0; ci < state.length; ci++) {
        var cr = state[ci].el.getBoundingClientRect();
        var ccx = cr.left + cr.width / 2, ccy = cr.top + cr.height / 2;
        var cdx = ccx - mouseX, cdy = ccy - mouseY;
        var cdist = Math.sqrt(cdx * cdx + cdy * cdy);
        if (cdist < HOVER_RADIUS && cdist < candidateDist) { candidateDist = cdist; candidate = ci; }
      }
    }

    if (candidate !== candidateIndex) {
      candidateIndex = candidate; // switched targets (or lost/gained one) — dwell has to start over
      hoverTimerMs = 0;
    } else if (candidate !== null) {
      hoverTimerMs = (rawSpeed <= MAX_HOVER_SPEED_PX) ? (hoverTimerMs + rawDtMs) : 0;
    }

    var nextHovered = (candidateIndex !== null && hoverTimerMs >= HOVER_DELAY_MS) ? candidateIndex : null;
    if (nextHovered !== hoveredIndex) {
      hoveredIndex = nextHovered;
      state.forEach(function (o, j) { o.el.classList.toggle('hy-dim', hoveredIndex !== null && j !== hoveredIndex); });
      if (hoveredIndex !== null) {
        blinkTo(true, ION_NAMES[hoveredIndex]);
      } else {
        blinkTo(false);
      }
    }

    var dragFactor = Math.pow(DRAG, steps);
    var springFactor = SPRING_K * steps;

    state.forEach(function (s, i) {
      var rect = s.el.getBoundingClientRect();
      var cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;

      if (hasMouse && (mvx || mvy)) {
        var dx = cx - mouseX, dy = cy - mouseY;
        var dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < PUSH_RADIUS) {
          var falloff = 1 - dist / PUSH_RADIUS;
          s.velX += mvx * IMPULSE_STRENGTH * falloff;
          s.velY += mvy * IMPULSE_STRENGTH * falloff;
        }
      }

      s.velX *= dragFactor;
      s.velY *= dragFactor;
      s.velX -= s.posX * springFactor;
      s.velY -= s.posY * springFactor;

      s.posX += s.velX * steps;
      s.posY += s.velY * steps;

      var mag = Math.sqrt(s.posX * s.posX + s.posY * s.posY);
      if (mag > MAX_DISPLACEMENT_PX) {
        var k = MAX_DISPLACEMENT_PX / mag;
        s.posX *= k; s.posY *= k;
      }

      var targetScale = (hoveredIndex === i) ? HOVER_SCALE : 1;
      s.scale += (targetScale - s.scale) * SCALE_EASE;

      var ux = s.posX / scale, uy = s.posY / scale; // screen px -> SVG user units
      s.el.style.transform = 'translate(' + ux.toFixed(3) + 'px,' + uy.toFixed(3) + 'px) scale(' + s.scale.toFixed(4) + ')'; // px required or CSSOM silently rejects the value; on an SVG element with no CSS box, "px" here maps 1:1 to user units
    });
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
})();
